import type { FC, ReactNode } from 'react';
import { useTranslation } from 'react-i18next';

import { Backdrop, CircularProgress, Stack, Typography } from '@mui/material';

import { ButtonFormWrapper } from '@shared/components/button_form_wrapper/ButtonFormWrapper';
import { testids } from '@shared/const/testid';
import { reactNodeToPlainText } from '@shared/lib/reactNodeToPlainText';
import type { ID } from '@shared/types/BaseQueryTypes';
import { Button } from '@shared/ui/button';

import { useTrueDeleteCarForm } from '../hooks/useTrueDeleteCarForm';

type DeleteTrueCarFormProps = {
  car: { id: ID; text: ReactNode } | null;
  closeModal: () => void;
};

const DeleteTrueCarFormInner: FC<{
  car: { id: ID; text: ReactNode };
  closeModal: () => void;
}> = ({ car, closeModal }) => {
  const { t } = useTranslation();
  const { onTrueDelete, isLoading } = useTrueDeleteCarForm(car.id, closeModal);
  return (
    <div>
      <Backdrop sx={{ color: '#fff', zIndex: (theme) => theme.zIndex.modal + 1 }} open={isLoading}>
        <CircularProgress color="inherit" />
      </Backdrop>
      <Typography marginBottom={2} fontWeight={700} variant="h6">
        {t('modals.vehicleDeletion')}
      </Typography>
      <Stack gap={3}>
        <Typography>
          {t('modals.confirmDeleteVehicle', { name: reactNodeToPlainText(car.text) })}
        </Typography>
        <ButtonFormWrapper>
          <Button
            testid={`${testids.POPUP_ACTION_BUTTON}`}
            onClick={onTrueDelete}
            disabled={isLoading}>
            {t('modals.yes')}
          </Button>
          <Button
            testid={`${testids.POPUP_CANCEL_BUTTON}`}
            onClick={closeModal}
            disabled={isLoading}>
            {t('modals.no')}
          </Button>
        </ButtonFormWrapper>
      </Stack>
    </div>
  );
};

export const DeleteTrueCarForm: FC<DeleteTrueCarFormProps> = ({ car, closeModal }) => {
  if (!car) return null;
  return <DeleteTrueCarFormInner car={car} closeModal={closeModal} />;
};
